"""Report the completed control without converting numerical searches into novelty."""
from common55 import *
import numpy as np

def main():
    p=OUT/'population55_v2.json';before=sha(p);s=read(p);q=read(OUT/'QUALIFICATION55_V2.json')
    assert s['status']=='COMPLETE_PRESPECIFIED_SCALAR_POPULATION_OBJECTIVE_CONTROL'
    assert len(s['cases'])==24 and len(s['all_144_numerical_trials'])==144
    ideal=[c for c in s['cases'] if c['reporting_jitter']==0]
    literal=[c for c in s['cases'] if c['reporting_jitter']!=0]
    stats={'ideal_cases':12,'literal_jitter_cases':12,'numerical_trials':144,'max_ideal_true_point_tightness_error':max(abs(c['true_point']['bound_gap']) for c in ideal),'max_ideal_best_a_error':max(c['best_numerical_trial']['a_error'] for c in ideal),'max_literal_best_a_error':max(c['best_numerical_trial']['a_error'] for c in literal),'max_ideal_best_objective_excess':max(c['best_numerical_trial']['objective_excess_over_true_lower_bound'] for c in ideal),'max_literal_best_objective_excess':max(c['best_numerical_trial']['objective_excess_over_true_lower_bound'] for c in literal),'trials_close_to_true_lower_bound':sum(c['starts_with_objective_excess_below_1e-6'] for c in s['cases']),'native_finite_loss_max_error':max(c['errors']['loss'] for c in q['native_finite_checks']),'native_finite_all_moment_max_error':max(max(c['errors'].values()) for c in q['native_finite_checks']),'reference_quadrature_max_error':q['reference_quadrature_max_error'],'target_sigma_point_max_error':q['target_sigma_point_max_error'],'minimum_random_bound_gap':min(c['minimum_random_bound_gap'] for c in s['cases']),'native_training_updates':0,'accepted_final_directions':0}
    table='| a true | Noise r | T | Jitter | Best numerical a | Absolute a error | Objective excess over true likelihood bound | Starts within1e-6 |\n|---:|---:|---:|---:|---:|---:|---:|---:|\n'
    for c in s['cases']:
        b=c['best_numerical_trial'];table+=f"|{c['a_star']}|{c['r']}|{c['T']}|{c['reporting_jitter']:.0e}|{b['a']:.9g}|{b['a_error']:.3g}|{b['objective_excess_over_true_lower_bound']:.3g}|{c['starts_with_objective_excess_below_1e-6']}/6|\n"
    status='No final research direction is accepted. The overall discovery objective remains active.\n\n'
    source='Source: [RP-GSSM](https://github.com/gatsby-sahani/rp-gssm/tree/a75225d5edceb972bb872dc9a335608733567dd4), checked unchanged against all21 pinned files. See PROTOCOL_V2.md and DERIVATION.md.\n\n'
    interpretation='For the ideal scalar in-model case, the auxiliary population objective has a proper-likelihood lower bound attained at the true point. This rules out an unavoidable population-objective bias as the explanation in this specific setting. The literal reporting-jitter convention is retained separately. Multi-start searches are numerical checks, not the global-optimum proof. Some starts can stop away from the best point; all144 results remain visible. Neither fact alone identifies the cause of C54\'s finite-bank multidimensional training failure.\n\n'
    results='# C55 population-objective control\n\n'+status+source+interpretation+table+'\nThe checks compare finite native code with independent scalar equations, reference Gaussian quadrature and exact target sigma-point expectation. Version1 stopped at the qualification stage because it omitted the source\'s jitter contribution to adjacent cross covariance; version2 corrected that copied convention. No native package, C54 checkpoint, C54 readout or C54 scored result changed. No new neural training was run.\n\nExact qualifications are in outputs/QUALIFICATION55_V2.json; all numerical starts are in outputs/population55_v2.csv and outputs/population55_v2.json. Full iteration traces stay on configured server artifact storage with hashes in the JSON.\n'
    docs={
      'README.md':results+'\nReproduction: use the existing pinned source/runtime layout, run scripts/qualify55_v2.py, then scripts/run_population55_v2.py, then scripts/analyze55_v1.py in a fresh cycle55 output directory. start55_v2.ps1 executes the first two stages durably on the existing Windows server. All writes preserve prior outputs.\n',
      'experimental_results.md':results,
      'literature_review.md':'# C55 literature boundary\n\n'+source+'The [ICML2026 paper](https://proceedings.mlr.press/v306/hromadka26a.html), Sections3.1–3.4 and AppendixC, separates the limiting-model identifiability statement from the approximation used during learning. Its recognition-factor definition includes the marginal prior. The present constant-precision scalar family does not automatically satisfy the full-image assumption in that theorem. The elementary Gaussian likelihood/variational-bound argument in DERIVATION.md is a control, not a refutation of the theorem or a new world-model method.\n\nGeneric variational-parameter bias and contrastive finite-reference gradient bias already have prior art recorded in C54. The next finite-bank investigation must retain ordinary full-reference/normalizer controls and cannot present a running normalizer or stop-gradient EM as an invention.\n',
      'baseline_registry.md':'# C55 baseline registry\n\n| Control | Executed scope | Interpretation |\n|---|---|---|\n| Unmodified native finite-bank loss | Four dummy scalar parameter points, independent loss and moment comparisons | Source-interface/numerical qualification |\n| Scalar closed population auxiliary loss |24 prescribed cases,144 generic-start bounded numerical optimizations | Mechanism control; no empirical neural fits |\n| Proper Gaussian RPM likelihood | Exact conditional likelihood under the same population reference law | Established likelihood control, not a new decoder |\n| True parameter point | Twelve ideal cases and twelve reporting-jitter cases | Known reference, not an optimizer initialization |\n\n'+source+status,
      'negative_evidence.md':'# C55 negative evidence\n\n'+interpretation+'The proposed unavoidable asymptotic scalar objective-bias explanation is not supported. C54\'s finite-bank and coupled-learning errors remain observed, but cannot be relabeled as this population defect. Numerical convergence of one start is not proof of practical learnability; unsuccessful starts are retained. Gaussian readout artifacts from C54 remain subject to their separate exact-oracle interpretation guard. No new architectural claim is established.\n\nThe first qualification failure was a missing term in the independent copied covariance-reporting convention, not an algorithmic discovery. Both versions and failure logs are preserved.\n',
      'hypothesis_space.md':'# C55 hypothesis update\n\n| Explanation | Evidence | Status |\n|---|---|---|\n| Unavoidable population objective bias in the realizable scalar Gaussian case | Properness/tightness argument plus native-matched exact expectations | Rejected for this stated case |\n| Finite reference banks alter the learning field | C54 frozen-reference controls; not isolated by a population optimum | Still requires direct finite-bank expectation test |\n| Coupled optimizer dynamics causes the C54 deficit | Some population starts can stop away from the best point, but different task/setup | Possible; not attributed to C54 by this control |\n| Reporting jitter explains the entire formal deficit | Literal and ideal conventions separated | Compare their scale; no such causal claim established |\n| A generic new variational/normalizer module is warranted | Extensive existing prior art and no independent useful method validation | Not established |\n\n'+status,
      'research_ideas.md':'# C55 candidate disposition\n\n'+status+'The remaining mechanistic lead is how finite reference estimation interacts with recognition and prior updates in a probabilistic state-learning objective. This is not yet a novel research problem: contrastive estimator bias and global normalizer methods are existing work. A useful framework contribution would need a differentiated conditional-dynamics capability, a competent existing repair, and independent nonlinear/real evidence. No method is proposed here merely because the C54 recipe fails.\n',
      'final_research_direction.md':'# C55 research disposition\n\n**Research Question:** Is the completed C54 learning deficit explained by an unavoidable bias at the ideal scalar population optimum?\n\n**Evidence:** Native-matched finite loss equations, independent reference quadrature and target integration,24 analytic cases and144 generic-start bounded numerical checks.\n\n**Existing Methods:** The Gaussian RPM reduces to a proper ordinary Gaussian likelihood under the stated reference law. Its ideal auxiliary bound touches that likelihood at the true point.\n\n**Proposed Idea:** None accepted. A new architecture is not justified by this control.\n\n**Falsification:** The true-point tightness and properness argument defeat the proposed unavoidable population-bias explanation in this case. They do not settle finite-bank or nonlinear behavior.\n\n**Feasibility:** Existing CPU runtime, zero new neural updates, no C54 data/model reads. Full numerical traces are on the authorized large disk.\n\n**Next Experiment:** At a known true population point, estimate finite-bank gradient expectations with controlled reference size and common random numbers. Separate prior and recognition blocks, full differentiation and fixed-posterior updates; compare to the exact zero population gradient and existing normalizer controls. This is an unexecuted discriminator, not a selected final research direction.\n\n'+status,
    }
    for name,text in docs.items():
        path=ROOT/name;assert not path.exists();path.write_text(text,encoding='utf-8')
    assert sha(p)==before
    dump(OUT/'ANALYSIS55_V1.json',{'utc':utc(),'status':'SCALAR_POPULATION_CONTROL_INTERPRETED_NO_NEW_DIRECTION_ACCEPTED','statistics':stats,'population_results_sha256':before,'qualification_sha256':sha(OUT/'QUALIFICATION55_V2.json'),'reports':{n:sha(ROOT/n) for n in docs},'analysis_script_sha256':sha(__file__),'overall_goal':'ACTIVE_UNACHIEVED'})
    print(json.dumps(stats),flush=True)

if __name__=='__main__':main()
